function bubbleSort(arr) {
  for (let i = 0; i < arr.length - 1; i++) {
    // 外层循环：控制排序轮数
    for (let j = 0; j < arr.length - 1 - i; j++) {
      // 内层循环：相邻比较
      if (arr[j] > arr[j+1]) {
        // 交换位置
        [arr[j], arr[j+1]] = [arr[j+1], arr[j]];
      }
    }
  }
}

public void bubbleSort(int[] arr) {
    int n = arr.length;
    // 外层循环：控制排序轮数
    for (int i = 0; i < n - 1; i++) {
        // 内层循环：比较相邻元素
        // 注意边界：n - 1 - i
        for (int j = 0; j < n - 1 - i; j++) {
            // 核心逻辑：相邻比较与交换
            if (arr[j] > arr[j + 1]) {
                // 交换元素
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

function bubbleSortOptimized(arr) {
  let n = arr.length;
  for (let i = 0; i < n - 1; i++) {
    // 1. 假设本轮已经有序
    let isSorted = true;

    for (let j = 0; j < n - 1 - i; j++) {
      if (arr[j] > arr[j + 1]) {
        // 2. 发生交换，说明假设不成立
        [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
        isSorted = false;
      }
    }

    // 3. 如果本轮未发生交换，提前结束
    if (isSorted) {
      break;
    }
  }
  return arr;
}

