stu[0].rank = 1; // 第一名
for(int i=1; i<n; i++) {
    if(stu[i].score == stu[i-1].score) {
        // 成绩相同，排名相同
        stu[i].rank = stu[i-1].rank;
    } else {
        // 成绩不同，排名等于数组下标+1
        stu[i].rank = i + 1;
    }
}
